const ANALYTICS_TABLE = 'eventos_web';
const ANALYTICS_ALLOWED = new Set([
  'pagina_visitada',
  'producto_abierto',
  'oferta_click',
  'canal_whatsapp_click',
  'canal_telegram_click',
  'cupon_copiado',
  'busqueda_realizada',
  'filtro_aplicado',
  'pagina_catalogo'
]);

function obtenerSesionId() {
  let id = sessionStorage.getItem('lmo_sesion_id');
  if (!id) {
    id = (globalThis.crypto?.randomUUID?.() || ('web-' + Date.now() + '-' + Math.random().toString(36).slice(2)));
    sessionStorage.setItem('lmo_sesion_id', id);
  }
  return id;
}

function obtenerDispositivo() {
  const ancho = window.innerWidth;
  if (ancho <= 560) return 'mobile';
  if (ancho <= 1024) return 'tablet';
  return 'desktop';
}

function obtenerFuente() {
  const params = new URLSearchParams(location.search);
  const utm = params.get('utm_source');
  if (utm) return utm.toLowerCase().slice(0, 80);

  if (!document.referrer) return 'directo';
  try {
    const host = new URL(document.referrer).hostname.replace(/^www\./, '');
    if (host.includes('facebook') || host.includes('fb.')) return 'facebook';
    if (host.includes('instagram')) return 'instagram';
    if (host.includes('tiktok')) return 'tiktok';
    if (host.includes('whatsapp')) return 'whatsapp';
    if (host.includes('telegram') || host.includes('t.me')) return 'telegram';
    if (host.includes('google')) return 'google';
    return host.slice(0, 80);
  } catch {
    return 'desconocido';
  }
}

function limpiarTextoAnalitica(valor, maximo = 180) {
  if (valor === null || valor === undefined) return null;
  return String(valor).replace(/\s+/g, ' ').trim().slice(0, maximo) || null;
}

function buscarProductoAnalitica(id) {
  if (!id || !Array.isArray(offers)) return null;
  return offers.find(o => String(o.id_mlm || o.id || '') === String(id)) || null;
}

async function registrarEvento(evento, datos = {}) {
  if (!ANALYTICS_ALLOWED.has(evento)) return;

  const registro = {
    evento,
    sesion_id: obtenerSesionId(),
    producto_id: limpiarTextoAnalitica(datos.producto_id, 80),
    producto_titulo: limpiarTextoAnalitica(datos.producto_titulo, 220),
    tienda: limpiarTextoAnalitica(datos.tienda, 120),
    precio: Number.isFinite(Number(datos.precio)) ? Number(datos.precio) : null,
    descuento: Number.isFinite(Number(datos.descuento)) ? Number(datos.descuento) : null,
    ubicacion: limpiarTextoAnalitica(datos.ubicacion, 80),
    dispositivo: obtenerDispositivo(),
    fuente: obtenerFuente(),
    pagina: limpiarTextoAnalitica(location.pathname || '/', 180),
    detalles: datos.detalles && typeof datos.detalles === 'object' ? datos.detalles : {}
  };

  try {
    const respuesta = await fetch(`${SUPABASE_URL}/rest/v1/${ANALYTICS_TABLE}`, {
      method: 'POST',
      keepalive: true,
      headers: {
        apikey: SUPABASE_KEY,
        Authorization: `Bearer ${SUPABASE_KEY}`,
        'Content-Type': 'application/json',
        Prefer: 'return=minimal'
      },
      body: JSON.stringify(registro)
    });

    if (!respuesta.ok && location.hostname === 'localhost') {
      console.warn('Supabase analytics:', respuesta.status, await respuesta.text());
    }
  } catch (error) {
    if (location.hostname === 'localhost') {
      console.warn('No se pudo registrar el evento:', error);
    }
  }
}

function datosProductoAnalitica(elemento) {
  const contenedor = elemento?.closest?.('[data-product-id]');
  const id = elemento?.dataset?.productId ||
    elemento?.dataset?.openProduct ||
    contenedor?.dataset?.productId || null;
  const producto = buscarProductoAnalitica(id);

  return {
    producto_id: id,
    producto_titulo: producto?.titulo || null,
    tienda: producto?.tienda_oficial || null,
    precio: producto?.p_act ?? null,
    descuento: producto?.pct_descuento ?? null
  };
}

