/* Delegacion: funciona tambien con tarjetas creadas despues de consultar Supabase. */
document.addEventListener('click', event => {
  const objetivo = event.target;

  const whatsapp = objetivo.closest?.('a[href*="whatsapp.com"],a[href*="wa.me"]');
  if (whatsapp) {
    registrarEvento('canal_whatsapp_click', {
      ubicacion: whatsapp.closest('.floating-channels') ? 'boton_flotante' : 'pagina',
      detalles: { texto: limpiarTextoAnalitica(whatsapp.textContent, 100) }
    });
    return;
  }

  const telegram = objetivo.closest?.('a[href*="t.me"],a[href*="telegram.me"]');
  if (telegram) {
    registrarEvento('canal_telegram_click', {
      ubicacion: telegram.closest('.floating-channels') ? 'boton_flotante' : 'pagina',
      detalles: { texto: limpiarTextoAnalitica(telegram.textContent, 100) }
    });
    return;
  }

  const copiar = objetivo.closest?.('.copy, .copy-product-coupon');
  if (copiar) {
    registrarEvento('cupon_copiado', {
      ubicacion: copiar.closest('#productModal') ? 'detalle_producto' : 'seccion_cupones',
      detalles: { codigo: limpiarTextoAnalitica(copiar.dataset.code, 80) }
    });
    return;
  }

  const enlaceOferta = objetivo.closest?.('a.market-action, a.offer, [data-offer-link]');
  if (enlaceOferta) {
    registrarEvento('oferta_click', {
      ...datosProductoAnalitica(enlaceOferta),
      ubicacion: enlaceOferta.closest('#productModal') ? 'detalle_producto' : 'tarjeta',
      detalles: { destino: limpiarTextoAnalitica(enlaceOferta.href, 300) }
    });
    return;
  }

  const abrirProducto = objetivo.closest?.('[data-open-product], .card[data-product-id]');
  if (abrirProducto && !objetivo.closest?.('a,button.copy,button.share-product')) {
    registrarEvento('producto_abierto', {
      ...datosProductoAnalitica(abrirProducto),
      ubicacion: abrirProducto.matches('.card') ? 'tarjeta' : 'boton_detalles'
    });
    return;
  }

  const filtroRapidoEl = objetivo.closest?.('.quick-filter');
  if (filtroRapidoEl) {
    registrarEvento('filtro_aplicado', {
      ubicacion: 'filtro_rapido',
      detalles: { filtro: limpiarTextoAnalitica(filtroRapidoEl.dataset.filter, 80) }
    });
    return;
  }

  const paginacion = objetivo.closest?.('.page-btn[data-page]');
  if (paginacion) {
    registrarEvento('pagina_catalogo', {
      ubicacion: 'paginacion',
      detalles: { pagina: Number(paginacion.dataset.page) || 1 }
    });
  }
});

['sort', 'dateScope'].forEach(id => {
  document.getElementById(id)?.addEventListener('change', event => {
    registrarEvento('filtro_aplicado', {
      ubicacion: id,
      detalles: { valor: limpiarTextoAnalitica(event.target.value, 80) }
    });
  });
});

let temporizadorBusquedaAnalitica;
document.getElementById('search')?.addEventListener('input', event => {
  clearTimeout(temporizadorBusquedaAnalitica);
  const termino = event.target.value.trim();
  if (termino.length < 3) return;

  temporizadorBusquedaAnalitica = setTimeout(() => {
    registrarEvento('busqueda_realizada', {
      ubicacion: 'buscador',
      detalles: {
        termino: limpiarTextoAnalitica(termino, 100),
        longitud: termino.length
      }
    });
  }, 800);
});




/* Modal compacto de suscripcion por correo */
const newsletterModal=document.getElementById('newsletterModal');
function abrirNewsletter(){if(!newsletterModal)return;newsletterModal.hidden=false;const dialog=newsletterModal.querySelector('.newsletter-modal-dialog');if(dialog)dialog.scrollTop=0;document.body.classList.add('modal-open');setTimeout(()=>document.getElementById('newsletterEmail')?.focus(),0)}
function cerrarNewsletter(){if(!newsletterModal)return;newsletterModal.hidden=true;document.body.classList.remove('modal-open')}
document.querySelectorAll('[data-open-newsletter]').forEach(boton=>boton.addEventListener('click',e=>{e.preventDefault();abrirNewsletter()}));document.querySelectorAll('[data-close-newsletter]').forEach(boton=>boton.addEventListener('click',e=>{e.preventDefault();cerrarNewsletter()}));document.addEventListener('click',e=>{if(e.target.closest('[data-open-newsletter]')){e.preventDefault();abrirNewsletter()}if(e.target.closest('[data-close-newsletter]')){e.preventDefault();cerrarNewsletter()}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&newsletterModal&&!newsletterModal.hidden)cerrarNewsletter()});

/* Suscripcion por correo y aviso de privacidad */
const newsletterForm=document.getElementById('newsletterForm'),newsletterEmail=document.getElementById('newsletterEmail'),newsletterConsent=document.getElementById('newsletterConsent'),newsletterMessage=document.getElementById('newsletterMessage'),newsletterSubmit=document.getElementById('newsletterSubmit'),policyModal=document.getElementById('policyModal');
function abrirPolitica(){if(!policyModal)return;policyModal.hidden=false;const dialog=policyModal.querySelector('.policy-dialog');if(dialog)dialog.scrollTop=0;document.body.classList.add('modal-open');setTimeout(()=>policyModal.querySelector('.policy-close')?.focus(),0)}
function cerrarPolitica(){if(!policyModal)return;policyModal.hidden=true;document.body.classList.remove('modal-open')}
document.addEventListener('click',e=>{if(e.target.closest('[data-open-policy]'))abrirPolitica();if(e.target.closest('[data-close-policy]'))cerrarPolitica()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&policyModal&&!policyModal.hidden)cerrarPolitica()});
function mostrarMensajeNewsletter(texto,tipo=''){if(!newsletterMessage)return;newsletterMessage.textContent=texto;newsletterMessage.className='newsletter-message'+(tipo?' '+tipo:'')}
newsletterForm?.addEventListener('submit',async e=>{e.preventDefault();const email=String(newsletterEmail?.value||'').trim().toLowerCase();if(!newsletterEmail.checkValidity()){mostrarMensajeNewsletter('Escribe un correo electrónico válido.','error');newsletterEmail.focus();return}if(!newsletterConsent?.checked){mostrarMensajeNewsletter('Necesitamos tu consentimiento para enviarte ofertas.','error');newsletterConsent.focus();return}newsletterSubmit.disabled=true;newsletterSubmit.textContent='Guardando…';mostrarMensajeNewsletter('');try{const respuesta=await fetch(`${SUPABASE_URL}/rest/v1/rpc/suscribir_email`,{method:'POST',headers:{apikey:SUPABASE_KEY,Authorization:`Bearer ${SUPABASE_KEY}`,'Content-Type':'application/json'},body:JSON.stringify({p_email:email,p_origen:obtenerFuente?.()||'web'})});if(!respuesta.ok){const detalle=await respuesta.text();let mensaje=`HTTP ${respuesta.status}`;try{const json=JSON.parse(detalle);mensaje=json.message||json.hint||json.code||mensaje}catch{}throw new Error(mensaje)}mostrarMensajeNewsletter('¡Listo! Tu correo quedó registrado para recibir ofertas.','success');newsletterForm.reset();setTimeout(cerrarNewsletter,1400)}catch(error){console.error('Error al registrar correo:',error);mostrarMensajeNewsletter('No pudimos guardar tu correo. Verifica que ejecutaste el SQL de suscriptores en Supabase.','error')}finally{newsletterSubmit.disabled=false;newsletterSubmit.textContent='Quiero recibir ofertas'}});

/* Boton flotante para volver al inicio */
const backToTop = document.getElementById('backToTop');
function actualizarBotonSubir() {
  if (!backToTop) return;
  backToTop.classList.toggle('show', window.scrollY > 520);
}
window.addEventListener('scroll', actualizarBotonSubir, { passive: true });
backToTop?.addEventListener('click', () => {
  window.scrollTo({
    top: 0,
    behavior: window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth'
  });
});
actualizarBotonSubir();



/* Retira el skeleton de la barra amarilla cuando sus datos estan listos. */
const statusBar=document.getElementById('statusBar');
const statusBarValues=['statusOffers','statusCoupons','statusUpdated'].map(id=>document.getElementById(id)).filter(Boolean);
function finalizarCargaStatusBar(){
  if(!statusBar)return;
  const listos=statusBarValues.length===3&&statusBarValues.every(el=>{
    const valor=el.textContent.trim().toLowerCase();
    return valor&&valor!=='...'&&valor!=='recientemente';
  });
  if(listos){
    statusBar.classList.remove('status-bar-loading');
    statusBar.setAttribute('aria-busy','false');
    statusBar.removeAttribute('aria-label');
  }
}
const statusBarObserver=new MutationObserver(finalizarCargaStatusBar);
statusBarValues.forEach(el=>statusBarObserver.observe(el,{childList:true,characterData:true,subtree:true}));
finalizarCargaStatusBar();

/* Retira el skeleton del resumen cuando Supabase termina de responder. */
const statsSummary=document.getElementById('statsSummary');
const statsCountElements=['offerCount','couponCount','bankCount'].map(id=>document.getElementById(id)).filter(Boolean);
function finalizarCargaResumen(){
  if(!statsSummary)return;
  const listos=statsCountElements.length===3&&statsCountElements.every(el=>el.textContent.trim()!==''&&el.textContent.trim()!=='…');
  if(listos){
    statsSummary.classList.remove('stats-loading');
    statsSummary.setAttribute('aria-busy','false');
    statsSummary.removeAttribute('aria-label');
  }
}
const statsObserver=new MutationObserver(finalizarCargaResumen);
statsCountElements.forEach(el=>statsObserver.observe(el,{childList:true,characterData:true,subtree:true}));
finalizarCargaResumen();

